package javax.microedition.lcdui.game;import javax.microedition.lcdui.Graphics;
public abstract class Layer {protected int x,y,width,height;private boolean visible=true;protected Layer(int w,int h){if(w<0||h<0)throw new IllegalArgumentException();width=w;height=h;}public int getX(){return x;}public int getY(){return y;}public int getWidth(){return width;}public int getHeight(){return height;}public void setPosition(int x,int y){this.x=x;this.y=y;}public void move(int dx,int dy){x+=dx;y+=dy;}public boolean isVisible(){return visible;}public void setVisible(boolean b){visible=b;}public abstract void paint(Graphics g);}
